b = cfirpm(20,[-1 -0.5 -0.4 0.3 0.4 1],[0 0 1 1 0 0]);
w = [-0.8 -0.2 0 0.2 0.9]*pi;
h = freqz(b,1,w);
fprintf('%d coefficients\n', numel(b));
disp(round(abs(h)*100)/100)

d = designfilt('lowpassfir','FilterOrder',20,'CutoffFrequency',0.3,'DesignMethod','window');
disp(size(d.Coefficients))
disp(round(d.Coefficients(9:13)*10000)/10000)

d = designfilt('lowpassiir','FilterOrder',4,'HalfPowerFrequency',0.3);
disp(size(d.Coefficients))
y = filter(d,[1 zeros(1,5)]);
disp(round(y*10000)/10000)

b = fir1(10,0.4);
disp(round(b*10000)/10000)
bh = fir1(10,0.4,'high');
disp(round(bh*10000)/10000)
h = freqz(b,1,[0 pi]);
disp(round(abs(h)*1000)/1000)

b = fircls(30,[0 0.5 1],[1 0],[1.02 0.01],[0.98 -0.01]);
[h,w] = freqz(b,1,512);
pb = abs(h(w<0.4*pi));
sb = abs(h(w>0.6*pi));
fprintf('passband %.3f to %.3f, stopband max %.3f\n', min(pb), max(pb), max(sb));

b = fircls1(30,0.4,0.02,0.01);
[h,w] = freqz(b,1,512);
pb = abs(h(w<0.3*pi));
sb = abs(h(w>0.5*pi));
fprintf('%d coefficients\n', numel(b));
fprintf('passband %.3f to %.3f, stopband max %.3f\n', min(pb), max(pb), max(sb));

[n,fo,ao,w] = firpmord([1500 2000],[1 0],[0.01 0.001],8000);
fprintf('order %d\n', n);
disp(fo.')
disp(ao.')
disp(round(w.'*1000)/1000)
b = firpm(n,fo,ao,w);
fprintf('%d coefficients\n', numel(b));

b = intfilt(2,3,0.9);
disp(round(b*10000)/10000)
x = sin(2*pi*0.05*(0:19));
xu = upsample(x,2);
y = filter(b,1,[xu zeros(1,5)]);
y = y(6:end);
t = sin(2*pi*0.05*(0:0.5:19.5));
k = 11:30;
fprintf('error at the new points: %.4f\n', max(abs(y(k)-t(k))))
fprintf('error at the original points: %.4f\n', max(abs(y(1:2:end)-t(1:2:end))))

[n,Wn,beta,ftype] = kaiserord([1500 1600],[1 0],[0.01 0.01],8000);
fprintf('order %d, Wn %.4f, beta %.4f, type %s\n', n, Wn, beta, ftype);
b = fir1(n,Wn,ftype,kaiser(n+1,beta),'noscale');
fprintf('%d coefficients\n', numel(b));

[b,a] = maxflat(4,2,0.3);
disp(round(b*10000)/10000)
disp(round(a*10000)/10000)
h = freqz(b,a,[0 0.3*pi]);
disp(round(abs(h)*1000)/1000)
bs = maxflat(6,'sym',0.4);
disp(round(bs*10000)/10000)

[n,Wn] = buttord(0.2,0.3,1,40);
fprintf('order %d, Wn %.4f\n', n, Wn);
[b,a] = butter(n,Wn);
h = freqz(b,a,[0.2 0.3]*pi);
disp(round(20*log10(abs(h))*100)/100)

