[b,a] = yulewalk(6,[0 0.3 0.4 1],[1 1 0 0]);
disp(round(b*10000)/10000)
disp(round(a*10000)/10000)
h = freqz(b,a,[0.1 0.8]*pi);
disp(round(abs(h)*100)/100)
disp(all(abs(roots(a)) < 1))

a = poly([0.5 0.4]);
b = polyscale(a,2);
disp(round(b*10000)/10000)
disp(roots(b).')

